import{_ as t,o as e,c as r,a2 as o}from"./chunks/framework.GbRRgL9t.js";const u=JSON.parse('{"title":"管理后台","description":"","frontmatter":{},"headers":[],"relativePath":"guide/administration.md","filePath":"guide/administration.md","lastUpdated":1789902237000}'),i={name:"guide/administration.md"};function n(l,a,d,s,h,c){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="管理后台" tabindex="-1">管理后台 <a class="header-anchor" href="#管理后台" aria-label="Permalink to &quot;管理后台&quot;">​</a></h1><p>面向管理员的治理手册。管理相关能力主要在<strong>管理面板</strong>中，接口实现见<a href="./../api/admin.html">管理端 API</a>。</p><h2 id="入口与权限" tabindex="-1">入口与权限 <a class="header-anchor" href="#入口与权限" aria-label="Permalink to &quot;入口与权限&quot;">​</a></h2><p>仅管理员账号可用管理面板。所有管理操作均受 <code>admin</code> 角色限制，会写入审计日志。</p><h2 id="用户管理" tabindex="-1">用户管理 <a class="header-anchor" href="#用户管理" aria-label="Permalink to &quot;用户管理&quot;">​</a></h2><ul><li><strong>用户列表</strong>：查看全部用户及状态（激活 / 待审 / 封禁）。</li><li><strong>新增用户</strong>：<code>npm run adduser -- &lt;用户名&gt; [密码]</code> 或管理面板一键新增。</li><li><strong>删除用户</strong>：移除用户。</li><li><strong>重命名</strong>：修改用户名。</li><li><strong>改头像</strong>：设置用户头像。</li><li><strong>重置密码</strong>：为用户设置新密码。</li></ul><h2 id="注册审核" tabindex="-1">注册审核 <a class="header-anchor" href="#注册审核" aria-label="Permalink to &quot;注册审核&quot;">​</a></h2><p>开放注册产生的账号可能进入 <strong>pending</strong>（待审核）状态：</p><ul><li><strong>通过</strong>：账号激活，用户可登录。</li><li><strong>拒绝</strong>：账号被拒，无法登录。</li><li>未通过审核的账号登录时返回 403 对应提示。</li></ul><h2 id="举报与处罚" tabindex="-1">举报与处罚 <a class="header-anchor" href="#举报与处罚" aria-label="Permalink to &quot;举报与处罚&quot;">​</a></h2><ul><li><strong>举报处理</strong>：查看用户上报的举报（<code>/api/admin/reports</code>），可<strong>驳回</strong>或<strong>执行处罚</strong>。</li><li><strong>处罚类型</strong>：禁言（mute）、封禁（ban）、IP 封禁（ipBan）。</li><li><strong>奖惩记录</strong>：查看全部处罚（<code>/api/admin/penalties</code>），可<strong>撤销</strong>已有处罚。</li><li><strong>自动通知</strong>：执行处罚后，系统自动向被处罚用户写入一条站内「通知」，并在其实时连接上推送 <code>penalty</code> 消息（前端禁用输入）。</li></ul><h2 id="公告发布" tabindex="-1">公告发布 <a class="header-anchor" href="#公告发布" aria-label="Permalink to &quot;公告发布&quot;">​</a></h2><p>发布系统级公告（全员可见，出现在每用户信箱「公告」标签）。可删除已有公告。</p><h2 id="文件管理" tabindex="-1">文件管理 <a class="header-anchor" href="#文件管理" aria-label="Permalink to &quot;文件管理&quot;">​</a></h2><ul><li>查看已上传文件列表（与 <code>FILE_TTL_DAYS</code> 保留策略配合）。</li><li>可手动删除指定文件。</li></ul><h2 id="操作日志" tabindex="-1">操作日志 <a class="header-anchor" href="#操作日志" aria-label="Permalink to &quot;操作日志&quot;">​</a></h2><ul><li>分页查看审计 / 操作日志（登录、登出、发消息、上传、处罚、举报等活动）与来源 IP。</li><li>全局所有 HTTP 请求与 WebSocket 连接额外写入 <code>data/access.log</code>（可配合外部监控）。</li></ul><h2 id="依赖命令行" tabindex="-1">依赖命令行 <a class="header-anchor" href="#依赖命令行" aria-label="Permalink to &quot;依赖命令行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>npm run adduser -- &lt;用户名&gt; [新密码]</code></td><td>新增/重置用户密码（服务端命令行）</td></tr></tbody></table><p>更多安全与数据说明见<a href="./../getting-started/configuration.html">配置说明 · 内置安全限制</a>。</p>',20)])])}const p=t(i,[["render",n]]);export{u as __pageData,p as default};
